"""
INSTALADOR de la app Facturas.

Correr una sola vez dentro del repo nuevo "Facturas":
    python crear_app_facturas.py
Crea todos los archivos de la app en la carpeta actual.
Despues se hace commit/push y se borra este archivo.
"""
import base64, os

ARCHIVOS = {
    'actualizar.py': '',
    'build_exe.bat': '',
    'config.py': '',
    'excel_manager.py': '',
    'gmail_client.py': '',
    'main.py': '',
    'pdf_parser.py': '',
    'primera_vez.bat': '',
    'procesador.py': '',
    'procesar.bat': '',
    'proveedores.xlsx': '',
    'reconciliacion.py': '',
    'requirements.txt': 'cGRmcGx1bWJlcj49MC45LjAKcHltdXBkZj49MS4yMy4wCmdvb2dsZS1hdXRoPj0yLjAuMApnb29nbGUtYXV0aC1vYXV0aGxpYj49MS4wLjAKZ29vZ2xlLWFwaS1weXRob24tY2xpZW50Pj0yLjAuMApvcGVucHl4bD49My4wLjAKUHlRdDU+PTUuMTUuMAo=',
    'test_parser.py': '',
    'ventana.py': '',
    'ProcesadorFacturas.spec': '',
    'SETUP.md': '',
    '.gitignore': '',
    'README.md': '',
    'COMO_ACTUALIZAR.md': '',
}

def main():
    for nombre, b64 in ARCHIVOS.items():
        datos = base64.b64decode(b64)
        with open(nombre, "wb") as f:
            f.write(datos)
        print(f"  creado: {nombre}")
    print()
    print(f"Listo: {len(ARCHIVOS)} archivos creados.")
    print("Falta solo (si usan Gmail): copiar credentials.json a mano.")

if __name__ == "__main__":
    main()
